    medRef('ibuprofen','Ibuprofen','200 MG','Oral; Tablet','NSAID analgesic','Pain, fever, or inflammation.','Assess pain/temp, renal function, bleeding risk, GI history, BP, and duplicate NSAIDs.'),
    medRef('sodium-chloride-flush','0.9% Sodium Chloride Flush','10 ML','Intravenous; Injectable','IV flush','IV line patency maintenance.','Verify line/site, compatibility, patency, and flush technique.'),
    medRef('amiodarone','Amiodarone HCl','150 MG/3 ML','Injection; Injectable','High-alert antiarrhythmic','Life-threatening arrhythmias when ordered.','Monitor ECG, BP, electrolytes, IV site, infusion compatibility, and pulmonary/hepatic/thyroid risks.'),
    medRef('cefotaxime','Cefotaxime Sodium','2 G/VIAL','Intramuscular, Intravenous; Injectable','Cephalosporin antibiotic','Susceptible bacterial infections.','Check allergy, culture data, renal dosing, IV site, and infusion timing.')
